import { TASKS, BUDGET_KEYS } from './data.js';
export function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function validDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00');return !Number.isNaN(d.getTime())&&`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`===v&&d.getFullYear()>=2020&&d.getFullYear()<=2100;}
export function cleanState(raw){const r=raw&&typeof raw==='object'?raw:{};return {start:validDate(r.start)?r.start:'',note:typeof r.note==='string'?r.note.slice(0,5000):'',tasks:Object.fromEntries(TASKS.map(([id])=>[id,r.tasks?.[id]===true])),budget:Object.fromEntries(BUDGET_KEYS.map(k=>[k,typeof r.budget?.[k]==='number'&&Number.isFinite(r.budget[k])&&r.budget[k]>=0&&r.budget[k]<=100000?r.budget[k]:null]))};}
export function totalBudget(b){return(b.flight||0)*4+(b.stay||0)+(b.car||0)+(b.road||0)+(b.food||0)*40+(b.fun||0)*4+(b.extra||0);}
export function maps(d){const u=new URL(d.origin?'https://www.google.com/maps/dir/':'https://www.google.com/maps/search/');u.searchParams.set('api','1');if(d.origin){u.searchParams.set('origin',d.origin);u.searchParams.set('destination',d.destination);u.searchParams.set('travelmode','driving');if(d.waypoints)u.searchParams.set('waypoints',d.waypoints);}else u.searchParams.set('query',d.map);return u.href;}
export function nextRevision(revision){if(!Number.isInteger(revision)||revision<0||revision>=2147483647)throw Error('Ungültiger Planungsstand');return revision+1;}
